import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] x = new int[6];
        int sum = 0;

        for (int i = 0; i < 6; i++) {
            x[i] = sc.nextInt();
            sum += x[i];
        }

        if (sum % 3 != 0) {
            System.out.println("N");
            return;
        }

        int target = sum / 3;

        for (int i = 0; i < 6; i++) {
            if (x[i] != target) continue;

            for (int j = 0; j < 6; j++) {
                if (j == i) continue;
                for (int k = j + 1; k < 6; k++) {
                    if (k == i) continue;
                    if (x[j] + x[k] == target) {
                        System.out.println("S");
                        return;
                    }
                }
            }
        }

        System.out.println("N");
    }
}
